import { NgModule, ModuleWithProviders } from '@angular/core';
import { CommonModule } from '@angular/common';

import { PaginationComponent } from './pagination.component';
import { PaginationModule as ngxPaginationModule, PaginationConfig } from 'ngx-bootstrap/pagination';
import { IconDirective } from 'espd-common/icon';
import { MessageModule } from 'espd-common/i18n';

export function getPaginationConfig(): PaginationConfig {
	return Object.assign(new PaginationConfig(), {
		main: {
			itemsPerPage: 10,
			rotate: true,
			maxSize: 3,
			directionLinks: false
		}
	});
}

@NgModule({
	imports: [
		CommonModule,
		ngxPaginationModule,
		IconDirective,
		MessageModule
	],
	declarations: [
		PaginationComponent
	],
	exports: [
		PaginationComponent
	]
})
export class PaginationModule {
	public static forRoot(): ModuleWithProviders<PaginationModule> {
		return {
			ngModule: PaginationModule,
			providers: [
				{ provide: PaginationConfig, useFactory: getPaginationConfig }
			]
		};
	}
}